import icontract
from typing import List


def euclid_mod(x: int, y: int) -> int:
    """Euclidean remainder of x divided by y (y != 0): always 0 <= r < abs(y)."""
    return x % abs(y)


@icontract.require(lambda a, b: len(a) == len(b) and len(a) > 0)
@icontract.require(lambda b: all(y != 0 for y in b))
@icontract.ensure(lambda a, b, result: len(result) == len(a) and all(
    result[i] == euclid_mod(a[i], b[i]) for i in range(len(result))))
def elementWiseModulo(a: List[int], b: List[int]) -> List[int]:
    result = []
    for i in range(len(a)):
        result.append(a[i] % abs(b[i]))
    return result
